#!/usr/bin/env python3
"""Validate the actual production serializer output generated by the C++ fixture.
Usage: python3 platform_hook_probe_report.py <collector-fixture-report.json> <...html>
"""
import json
import pathlib
import sys
from html.parser import HTMLParser

class Inspect(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.tags = []
        self.attrs = []
        self.script = False
        self.scripts = []
        self.cells = []
    def handle_starttag(self, tag, attrs):
        self.tags.append(tag)
        self.attrs.extend(attrs)
        if tag == 'script':
            self.script = True
            self.scripts.append('')
    def handle_endtag(self, tag):
        if tag == 'script':
            self.script = False
    def handle_data(self, data):
        if self.script:
            self.scripts[-1] += data
        else:
            self.cells.append(data)

jpath, hpath = map(pathlib.Path, sys.argv[1:3])
data = json.loads(jpath.read_text(encoding='utf-8'))
html = hpath.read_text(encoding='utf-8')
assert data['format'] == 'ra2-readonly-hook-probe-v1'
assert data['reference_catalog']['entry_count'] == 161
assert data['writer_attribution'].startswith('unknown;')
assert data['instruction_boundaries_verified'] is False
assert data['modules'][0]['baseline_file']['sha256']
assert data['modules'][0]['name'].startswith('</script><img')
assert all(len(d['expected_sample_hex'].split()) <= 32 and len(d['actual_sample_hex'].split()) <= 32 for d in data['differences'])
assert all(len(d['chain']) <= 8 for d in data['differences'])
assert all(len(d['reference_intersections']) <= 8 for d in data['differences'])
p = Inspect()
p.feed(html)
assert p.tags.count('script') == 1
assert 'img' not in p.tags
assert not any(k.startswith('on') for k, v in p.attrs)
assert 'alert(1)' not in p.scripts[0]
assert '.textContent' in p.scripts[0]
assert 'innerHTML' not in p.scripts[0]
assert "<img src=x onerror=alert(1)>" in ''.join(p.cells)
assert 'default-src' in html and 'Content-Security-Policy' in html
assert len(jpath.read_bytes()) < 32 * 1024 * 1024
assert len(hpath.read_bytes()) < 32 * 1024 * 1024
print('PASS production JSON parses, 161-entry references, candidate/sample bounds, HTML parser confirms hostile text is not executable markup; static filter only')
